#!/usr/bin/env node
/**
 * Design drift ledger (JOV-6850): the deterministic half of the
 * docs/design-system drift audit, regenerated by machine.
 *
 * For every authed page under apps/web/app/app/(shell)/** the script walks the
 * transitive import graph inside apps/web (`@/` aliases + relative imports;
 * packages and node_modules are skipped) and counts drift signals per route.
 * Aggregate counts are taken over the union of reachable files, so a shared
 * component counts once. Registry `penRootId: null` entries, parallel
 * component families, and danger-alias sprawl are added to the aggregate.
 *
 * Outputs:
 *   docs/design-system/drift-ledger.json  (stable key order, sorted routes)
 *   docs/design-system/DRIFT_LEDGER.md    (table between the ledger markers)
 *
 * Usage:
 *   node scripts/design-drift-ledger.mjs --update   rewrite JSON + markdown
 *   node scripts/design-drift-ledger.mjs --check    shrink-only ratchet
 *   (--root <dir> points at another repo root; used by the tests)
 *
 * --check exits 1 when an aggregate count grew versus the committed JSON or
 * the committed markdown block no longer renders from that JSON; exit 2 on
 * unreadable inputs. Shrink passes and prints a hint to run --update.
 */
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  ARBITRARY_VALUE_PATTERN,
  LINEAR_NAMESPACE_PATTERN,
} from './design-system-source-ratchet.mjs';

const THIS_DIR = path.dirname(fileURLToPath(import.meta.url));
export const REPO_ROOT = path.join(THIS_DIR, '..');
export const SCHEMA = 'jovie.design-drift-ledger/v1';
export const LEDGER_JSON = 'docs/design-system/drift-ledger.json';
export const LEDGER_MD = 'docs/design-system/DRIFT_LEDGER.md';
export const MD_START = '<!-- drift-ledger:start -->';
export const MD_END = '<!-- drift-ledger:end -->';
const WEB = 'apps/web';
const SHELL_DIR = 'app/app/(shell)';
const REGISTRIES = {
  appScreens: 'data/appScreens/registry.ts',
  componentRegistry: 'data/designSystem/componentRegistry.ts',
};

const PALETTE =
  'slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose';
const COLOR_UTILITY =
  'text|bg|border|ring|fill|stroke|from|via|to|outline|divide|placeholder|decoration|accent|caret|shadow';

/** Per-file signals, in ledger column order. */
export const SIGNALS = Object.freeze({
  rawPalette: new RegExp(
    `(?<![\\w-])(?:${COLOR_UTILITY})-(?:(?:${PALETTE})-\\d{2,3}|white|black)(?![\\w-])|(?<![\\w&])#(?:[0-9a-fA-F]{8}|[0-9a-fA-F]{6}|[0-9a-fA-F]{3,4})(?![\\w-])`,
    'g'
  ),
  arbitrary: ARBITRARY_VALUE_PATTERN,
  rawButton: /<button(?=[\s/>])/g, // locked to raw-button-ratchet.test.ts
  linearToken: LINEAR_NAMESPACE_PATTERN,
  oversizeControl: /(?<![\w-])(?:h|size)-1[12](?![\w./-])/g,
  dangerAlias:
    /(?<![\w-])(?:text|bg|border)-(?:error|destructive|red)(?:-\d{2,3})?(?![\w-])/g,
});

/** Parallel component families under apps/web/components (file names). */
export const FAMILIES = Object.freeze({
  statusFamily: /(?:Status(?:Pill|Badge|Dot|Glyph)|Glyph)\.tsx$/,
  entityHeaderFamily: /(?:Entity|Drawer|Member|Detail)Header(?:Card)?\.tsx$/,
  railFamily: /Rail\.tsx$/,
});

/**
 * Signals count only in the authed surface the audit scoped (route-owned
 * code). Shared design-system layers reached by those routes get their own
 * tally. Everything else (lib, hooks, providers) is traversed, not counted.
 */
export const ROUTE_LAYER = /^(?:app\/app|components\/(?:features|jovie))\//;
export const SHARED_LAYER =
  /^components\/(?:atoms|molecules|organisms|shell)\//;

const ALIASES = [
  ['@/atoms/', ['components/atoms/']],
  ['@/molecules/', ['components/molecules/']],
  ['@/organisms/', ['components/organisms/']],
  ['@/features/', ['components/features/']],
  ['@/app/', ['app/', 'app/app/']],
  ['@/', ['']],
];
const EXTENSIONS = ['', '.tsx', '.ts', '.jsx', '.js', '.mjs', '.css'];
const INDEXES = ['/index.tsx', '/index.ts', '/index.js'];
const SCANNED = /\.(?:tsx|ts|jsx|js|mjs|css)$/;
const IMPORT_PATTERNS = [
  /\b(?:import|export)\s[^'";]*?\bfrom\s*['"]([^'"]+)['"]/g,
  /\bimport\s*['"]([^'"]+)['"]/g,
  /\bimport\s*\(\s*['"]([^'"]+)['"]\s*\)/g,
];
const SKIP_DIRS = new Set(['node_modules', '.next', '.turbo', 'dist']);

function walk(dir, predicate, out = []) {
  if (!existsSync(dir)) return out;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (SKIP_DIRS.has(entry.name)) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, predicate, out);
    else if (predicate(entry.name)) out.push(full);
  }
  return out;
}

const countMatches = (source, pattern) =>
  (source.match(new RegExp(pattern.source, pattern.flags)) ?? []).length;

const toPosix = value => value.split(path.sep).join('/');

function createScanner(webRoot) {
  const sources = new Map();
  const edges = new Map();
  const read = file => {
    if (!sources.has(file)) sources.set(file, readFileSync(file, 'utf8'));
    return sources.get(file);
  };
  const resolveBase = base => {
    for (const candidate of [
      ...EXTENSIONS.map(ext => base + ext),
      ...INDEXES.map(ext => base + ext),
    ]) {
      if (
        SCANNED.test(candidate) &&
        existsSync(candidate) &&
        !candidate.includes(`${path.sep}node_modules${path.sep}`)
      ) {
        return candidate;
      }
    }
    return null;
  };
  const resolveSpecifier = (from, specifier) => {
    if (specifier.startsWith('.')) {
      return resolveBase(path.resolve(path.dirname(from), specifier));
    }
    for (const [prefix, targets] of ALIASES) {
      if (!specifier.startsWith(prefix)) continue;
      for (const target of targets) {
        const hit = resolveBase(
          path.join(webRoot, target, specifier.slice(prefix.length))
        );
        if (hit) return hit;
      }
      return null;
    }
    return null; // bare package specifiers live outside apps/web
  };
  const importsOf = file => {
    if (edges.has(file)) return edges.get(file);
    const found = new Set();
    if (!file.endsWith('.css')) {
      const source = read(file);
      for (const pattern of IMPORT_PATTERNS) {
        for (const match of source.matchAll(pattern)) {
          const hit = resolveSpecifier(file, match[1]);
          if (hit?.startsWith(webRoot + path.sep)) found.add(hit);
        }
      }
    }
    const list = [...found].sort();
    edges.set(file, list);
    return list;
  };
  const closure = entry => {
    const seen = new Set([entry]);
    const stack = [entry];
    while (stack.length > 0) {
      for (const next of importsOf(stack.pop())) {
        if (!seen.has(next)) {
          seen.add(next);
          stack.push(next);
        }
      }
    }
    return seen;
  };
  const signalCache = new Map();
  const signalsOf = file => {
    if (!signalCache.has(file)) {
      const source = read(file);
      signalCache.set(
        file,
        Object.fromEntries(
          Object.entries(SIGNALS).map(([key, re]) => [
            key,
            countMatches(source, re),
          ])
        )
      );
    }
    return signalCache.get(file);
  };
  const tally = (files, layer) => {
    /** @type {Record<string, number>} */
    const counts = { files: 0 };
    for (const key of Object.keys(SIGNALS)) counts[key] = 0;
    for (const file of files) {
      if (!layer.test(toPosix(path.relative(webRoot, file)))) continue;
      counts.files += 1;
      const signals = signalsOf(file);
      for (const key of Object.keys(SIGNALS)) counts[key] += signals[key];
    }
    return counts;
  };
  return { closure, tally };
}

export function routeForPage(shellRoot, pageFile) {
  const segments = toPosix(path.relative(shellRoot, path.dirname(pageFile)))
    .split('/')
    .filter(segment => segment && !/^\(.*\)$/.test(segment));
  return ['/app', ...segments].join('/');
}

/** Build the ledger object. Throws when a required input is unreadable. */
export function buildDriftLedger({ repoRoot = REPO_ROOT } = {}) {
  const webRoot = path.join(repoRoot, WEB);
  const shellRoot = path.join(webRoot, SHELL_DIR);
  if (!existsSync(shellRoot)) {
    throw new Error(`route root ${WEB}/${SHELL_DIR} is missing`);
  }
  const pages = walk(shellRoot, name => name === 'page.tsx').sort();
  if (pages.length === 0) throw new Error(`no page.tsx under ${SHELL_DIR}`);

  const scanner = createScanner(webRoot);
  const routes = {};
  const union = new Set();
  for (const page of pages) {
    const files = scanner.closure(page);
    for (const file of files) union.add(file);
    routes[routeForPage(shellRoot, page)] = scanner.tally(files, ROUTE_LAYER);
  }

  const registries = {};
  let penRootIdNull = 0;
  for (const [key, relative] of Object.entries(REGISTRIES)) {
    const file = path.join(webRoot, relative);
    if (!existsSync(file))
      throw new Error(`registry ${WEB}/${relative} is missing`);
    const source = readFileSync(file, 'utf8');
    const entries = countMatches(source, /\bpenRootId:(?!\s*string\b)/g);
    const nulls = countMatches(source, /\bpenRootId:\s*null\b/g);
    registries[key] = { entries, penRootIdNull: nulls };
    penRootIdNull += nulls;
  }

  const componentFiles = walk(
    path.join(webRoot, 'components'),
    name => name.endsWith('.tsx') && !/\.(?:test|stories)\.tsx$/.test(name)
  )
    .map(file => toPosix(path.relative(webRoot, file)))
    .sort();
  const families = {};
  for (const [key, pattern] of Object.entries(FAMILIES)) {
    families[key] = componentFiles.filter(file => pattern.test(file));
  }

  /** @type {Record<string, number>} */
  const aggregate = {
    routes: pages.length,
    ...scanner.tally(union, ROUTE_LAYER),
  };
  aggregate.penRootIdNull = penRootIdNull;
  for (const [key, list] of Object.entries(families)) {
    aggregate[key] = list.length;
  }

  const sortedRoutes = {};
  for (const route of Object.keys(routes).sort()) {
    sortedRoutes[route] = routes[route];
  }
  return {
    schema: SCHEMA,
    generatedBy: 'scripts/design-drift-ledger.mjs --update',
    aggregate,
    sharedLayers: scanner.tally(union, SHARED_LAYER),
    registries,
    families,
    routes: sortedRoutes,
  };
}

const SIGNAL_LABELS = {
  rawPalette: 'Raw palette',
  arbitrary: 'Arbitrary',
  rawButton: 'Raw button',
  linearToken: '--linear-*',
  oversizeControl: '44/48px',
  dangerAlias: 'Danger alias',
};
const AGGREGATE_LABELS = {
  routes: 'Routes scanned',
  files: 'Files counted (route-owned or shared layer)',
  rawPalette: 'Raw Tailwind palette utilities and hex colors',
  arbitrary: 'Arbitrary values',
  rawButton: 'Raw `<button>` tags',
  linearToken: 'Legacy `--linear-*` tokens',
  oversizeControl: 'Visible 44/48px controls (`h-11`, `h-12`, `size-*`)',
  dangerAlias: 'Danger alias utilities (`error`, `destructive`, `red`)',
  penRootIdNull: 'Registry entries with `penRootId: null`',
  statusFamily: 'Status pill, badge, dot, and glyph components',
  entityHeaderFamily: 'Entity header components',
  railFamily: 'Rail components',
};

/** Render the markdown block (between the markers) from a ledger object. */
export function renderMarkdownBlock(ledger) {
  const lines = [
    '',
    '| Aggregate | Count |',
    '|---|---:|',
    ...Object.entries(ledger.aggregate).map(
      ([key, value]) => `| ${AGGREGATE_LABELS[key] ?? key} | ${value} |`
    ),
    '',
    '| Shared design-system layers reached by routes | Count |',
    '|---|---:|',
    ...Object.entries(ledger.sharedLayers).map(
      ([key, value]) => `| ${AGGREGATE_LABELS[key] ?? key} | ${value} |`
    ),
    '',
    '| Registry | Entries | `penRootId: null` |',
    '|---|---:|---:|',
    ...Object.entries(ledger.registries).map(
      ([key, value]) => `| ${key} | ${value.entries} | ${value.penRootIdNull} |`
    ),
    '',
  ];
  const keys = Object.keys(SIGNAL_LABELS);
  const flagged = Object.entries(ledger.routes).filter(([, counts]) =>
    keys.some(key => counts[key] > 0)
  );
  lines.push(
    `Routes with at least one signal: ${flagged.length} of ${Object.keys(ledger.routes).length}.`,
    '',
    `| Route | Files | ${keys.map(key => SIGNAL_LABELS[key]).join(' | ')} |`,
    `|---|---:|${keys.map(() => '---:').join('|')}|`,
    ...flagged.map(
      ([route, counts]) =>
        `| \`${route}\` | ${counts.files} | ${keys.map(key => counts[key]).join(' | ')} |`
    ),
    ''
  );
  return lines.join('\n');
}

/**
 * Pretty JSON with one line per route: keeps the committed diff small enough
 * for the PR size cap. Biome ignores this generated file so format cannot
 * expand it; parse is identical.
 */
export function serializeLedger(ledger) {
  const { routes, ...rest } = ledger;
  const head = JSON.stringify(rest, null, 2).slice(0, -2);
  const rows = Object.entries(routes).map(
    ([route, counts]) =>
      `    ${JSON.stringify(route)}: ${JSON.stringify(counts)}`
  );
  return `${head},\n  "routes": {\n${rows.join(',\n')}\n  }\n}\n`;
}

function readBlock(markdown) {
  const start = markdown.indexOf(MD_START);
  const end = markdown.indexOf(MD_END);
  if (start === -1 || end === -1 || end < start) return null;
  return markdown.slice(start + MD_START.length, end);
}

/** Rewrite the JSON and the markdown block from the current source. */
export function updateDriftLedger({ repoRoot = REPO_ROOT } = {}) {
  const ledger = buildDriftLedger({ repoRoot });
  writeFileSync(path.join(repoRoot, LEDGER_JSON), serializeLedger(ledger));
  const mdPath = path.join(repoRoot, LEDGER_MD);
  const markdown = existsSync(mdPath)
    ? readFileSync(mdPath, 'utf8')
    : `# Design drift ledger\n\n${MD_START}\n${MD_END}\n`;
  if (readBlock(markdown) === null) {
    throw new Error(`${LEDGER_MD} is missing the drift-ledger markers`);
  }
  const start = markdown.indexOf(MD_START) + MD_START.length;
  const end = markdown.indexOf(MD_END);
  writeFileSync(
    mdPath,
    `${markdown.slice(0, start)}${renderMarkdownBlock(ledger)}${markdown.slice(end)}`
  );
  return ledger;
}

/**
 * Shrink-only verdict. Throws on unreadable inputs.
 * @returns {{ ok: boolean, issues: string[], shrunk: string[], ledger: object }}
 */
export function checkDriftLedger({ repoRoot = REPO_ROOT } = {}) {
  const jsonPath = path.join(repoRoot, LEDGER_JSON);
  const mdPath = path.join(repoRoot, LEDGER_MD);
  if (!existsSync(jsonPath)) throw new Error(`${LEDGER_JSON} is missing`);
  if (!existsSync(mdPath)) throw new Error(`${LEDGER_MD} is missing`);
  const committed = JSON.parse(readFileSync(jsonPath, 'utf8'));
  if (committed?.schema !== SCHEMA || typeof committed.aggregate !== 'object') {
    throw new Error(`${LEDGER_JSON} does not declare ${SCHEMA}`);
  }
  const block = readBlock(readFileSync(mdPath, 'utf8'));
  if (block === null) throw new Error(`${LEDGER_MD} is missing the markers`);

  const ledger = buildDriftLedger({ repoRoot });
  const issues = [];
  const shrunk = [];
  for (const section of ['aggregate', 'sharedLayers']) {
    for (const [key, value] of Object.entries(ledger[section])) {
      if (key === 'routes' || key === 'files') continue;
      const baseline = committed[section]?.[key] ?? 0;
      const label = `${section}.${key}`;
      if (value > baseline) {
        issues.push(`${label} grew to ${value} (ledger ${baseline})`);
      } else if (value < baseline) {
        shrunk.push(`${label} ${baseline} -> ${value}`);
      }
    }
  }
  if (block !== renderMarkdownBlock(committed)) {
    issues.push(`${LEDGER_MD} table is stale versus ${LEDGER_JSON}`);
  }
  return { ok: issues.length === 0, issues, shrunk, ledger };
}

function main(argv) {
  const rootIndex = argv.indexOf('--root');
  const repoRoot =
    rootIndex === -1 ? REPO_ROOT : path.resolve(argv[rootIndex + 1]);
  const tag = '[design-drift-ledger]';
  try {
    if (argv.includes('--update')) {
      const ledger = updateDriftLedger({ repoRoot });
      console.log(`${tag} wrote ${LEDGER_JSON} and ${LEDGER_MD}`);
      console.log(JSON.stringify(ledger.aggregate));
      return 0;
    }
    const result = checkDriftLedger({ repoRoot });
    if (!result.ok) {
      console.error(`${tag} FAIL`);
      for (const issue of result.issues) console.error(`  ${issue}`);
      console.error(
        '  Remove the new drift, or run `pnpm design:drift-ledger` if the growth is intended.'
      );
      return 1;
    }
    console.log(`${tag} PASS ${JSON.stringify(result.ledger.aggregate)}`);
    if (result.shrunk.length > 0) {
      console.log(
        `${tag} drift shrank (${result.shrunk.join(', ')}); run \`pnpm design:drift-ledger\` to lock it in`
      );
    }
    return 0;
  } catch (error) {
    console.error(
      `${tag} unreadable input: ${error instanceof Error ? error.message : error}`
    );
    return 2;
  }
}

if (
  process.argv[1] &&
  fileURLToPath(import.meta.url) === path.resolve(process.argv[1])
) {
  process.exitCode = main(process.argv.slice(2));
}
